export function getLogos(): BrandLogo[] {
  return BRAND_LOGOS;
}

export function getLogosForCompany(company: string): BrandLogo[] {
  return BRAND_LOGOS.filter((l) => l.company === company);
}

export function searchLogos(q: string): BrandLogo[] {
  const needle = q.trim().toLowerCase();
  if (!needle) return BRAND_LOGOS;
  return BRAND_LOGOS.filter((l) => l.company.toLowerCase().includes(needle));
}
